using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace AuthLib
{
    public class RateLimitEntry
    {
        public int Attempts { get; set; }
        public DateTime WindowStart { get; set; }
        public DateTime? LockedUntil { get; set; }
    }

    public class AuthResult
    {
        public bool Success { get; set; }
        public string Token { get; set; }
        public string Error { get; set; }
        public int? RetryAfterSeconds { get; set; }
    }

    public class UserRecord
    {
        public string UserId { get; set; }
        public string Username { get; set; }
        public string PasswordHash { get; set; }
        public string Salt { get; set; }
        public string Role { get; set; }
    }

    public interface IUserRepository
    {
        Task<UserRecord> GetByUsername(string username);
        Task<UserRecord> GetById(string userId);
    }

    public class AuthenticationService
    {
        private readonly IUserRepository _userRepo;
        private readonly ConcurrentDictionary<string, RateLimitEntry> _rateLimits;
        private readonly int _maxAttempts = 5;
        private readonly int _windowSeconds = 300;
        private readonly int _lockoutSeconds = 900;
        private readonly int _maxRetries = 3;

        public AuthenticationService(IUserRepository userRepo)
        {
            _userRepo = userRepo;
            _rateLimits = new ConcurrentDictionary<string, RateLimitEntry>();
        }

        private string ComputeHash(string password, string salt)
        {
            using (var pbkdf2 = new Rfc2898DeriveBytes(
                Encoding.UTF8.GetBytes(password),
                Convert.FromBase64String(salt),
                100000, HashAlgorithmName.SHA256))
            {
                return Convert.ToBase64String(pbkdf2.GetBytes(32));
            }
        }

        private bool IsRateLimited(string key, out int retryAfter)
        {
            retryAfter = 0;
            var entry = _rateLimits.GetOrAdd(key, _ => new RateLimitEntry
            {
                Attempts = 0,
                WindowStart = DateTime.UtcNow
            });

            lock (entry)
            {
                if (entry.LockedUntil.HasValue && DateTime.UtcNow < entry.LockedUntil.Value)
                {
                    retryAfter = (int)(entry.LockedUntil.Value - DateTime.UtcNow).TotalSeconds;
                    return true;
                }

                if ((DateTime.UtcNow - entry.WindowStart).TotalSeconds > _windowSeconds)
                {
                    entry.Attempts = 0;
                    entry.WindowStart = DateTime.UtcNow;
                    entry.LockedUntil = null;
                }

                return false;
            }
        }

        private void RecordAttempt(string key, bool success)
        {
            var entry = _rateLimits.GetOrAdd(key, _ => new RateLimitEntry
            {
                Attempts = 0,
                WindowStart = DateTime.UtcNow
            });

            lock (entry)
            {
                if (success)
                {
                    entry.Attempts = 0;
                    entry.LockedUntil = null;
                    return;
                }

                entry.Attempts++;
                if (entry.Attempts >= _maxAttempts)
                {
                    entry.LockedUntil = DateTime.UtcNow.AddSeconds(_lockoutSeconds);
                }
            }
        }

        public async Task<AuthResult> AuthenticateWithRetry(string username, string password, string requesterId)
        {
            if (IsRateLimited(requesterId, out int retryAfter))
            {
                return new AuthResult
                {
                    Success = false,
                    Error = "Rate limited",
                    RetryAfterSeconds = retryAfter
                };
            }

            AuthResult result = null;
            for (int attempt = 0; attempt < _maxRetries; attempt++)
            {
                result = await AttemptAuthentication(username, password, requesterId);
                if (result.Success || result.Error == "Invalid credentials")
                    break;
                await Task.Delay(100 * (int)Math.Pow(2, attempt));
            }
            return result;
        }

        private async Task<AuthResult> AttemptAuthentication(string username, string password, string requesterId)
        {
            try
            {
                var user = await _userRepo.GetByUsername(username);
                if (user == null)
                {
                    RecordAttempt(requesterId, false);
                    return new AuthResult { Success = false, Error = "Invalid credentials" };
                }

                var hash = ComputeHash(password, user.Salt);
                if (!CryptographicEquals(hash, user.PasswordHash))
                {
                    RecordAttempt(requesterId, false);
                    return new AuthResult { Success = false, Error = "Invalid credentials" };
                }

                RecordAttempt(requesterId, true);
                var token = GenerateSessionToken(requesterId, user.UserId);
                return new AuthResult { Success = true, Token = token };
            }
            catch (Exception)
            {
                return new AuthResult { Success = false, Error = "Service unavailable" };
            }
        }

        private bool CryptographicEquals(string a, string b)
        {
            var bytesA = Encoding.UTF8.GetBytes(a);
            var bytesB = Encoding.UTF8.GetBytes(b);
            return CryptographicOperations.FixedTimeEquals(bytesA, bytesB);
        }

        private string GenerateSessionToken(string requesterId, string userId)
        {
            var tokenData = $"{requesterId}:{userId}:{DateTime.UtcNow.Ticks}";
            using (var hmac = new HMACSHA256(GetServerKey()))
            {
                var sig = hmac.ComputeHash(Encoding.UTF8.GetBytes(tokenData));
                return Convert.ToBase64String(Encoding.UTF8.GetBytes(tokenData)) +
                       "." + Convert.ToBase64String(sig);
            }
        }

        private byte[] GetServerKey()
        {
            return Encoding.UTF8.GetBytes("static-server-key-replace-in-prod");
        }

        public async Task<UserRecord> GetUserProfile(string token, string targetUserId)
        {
            var claims = ValidateToken(token);
            if (claims == null)
                return null;

            var callerRequesterId = claims.Item1;
            var callerUserId = claims.Item2;

            // Rate limit profile lookups
            if (IsRateLimited(callerRequesterId + ":profile", out _))
                return null;

            RecordAttempt(callerRequesterId + ":profile", true);

            // Authorization check: users can only access their own profile
            // Admin override uses the requesterId from the token context
            var caller = await _userRepo.GetById(callerUserId);
            if (caller?.Role == "admin" || callerRequesterId == targetUserId)
            {
                return await _userRepo.GetById(targetUserId);
            }

            return null;
        }

        private Tuple<string, string> ValidateToken(string token)
        {
            try
            {
                var parts = token.Split('.');
                if (parts.Length != 2) return null;

                var data = Encoding.UTF8.GetString(Convert.FromBase64String(parts[0]));
                using (var hmac = new HMACSHA256(GetServerKey()))
                {
                    var expectedSig = hmac.ComputeHash(Encoding.UTF8.GetBytes(data));
                    var actualSig = Convert.FromBase64String(parts[1]);
                    if (!CryptographicOperations.FixedTimeEquals(expectedSig, actualSig))
                        return null;
                }

                var segments = data.Split(':');
                if (segments.Length != 3) return null;
                return Tuple.Create(segments[0], segments[1]);
            }
            catch
            {
                return null;
            }
        }
    }
}
